'use client'

import type { ComponentProps } from 'react'
import { useState } from 'react'
import { Avatar, AvatarFallback, AvatarImage } from '@astrale-os/ui/avatar'
import { Button } from '@astrale-os/ui/button'
import { Badge } from '@astrale-os/ui/badge'
import {
  Kanban,
  KanbanBoard,
  KanbanColumn,
  KanbanColumnContent,
  KanbanColumnHandle,
  KanbanItem,
  KanbanItemHandle,
  KanbanOverlay
} from '@/components/ui/kanban'

import { cn } from '@astrale-os/ui/class-name'
import { CalendarClockIcon, GripVerticalIcon } from "lucide-react"

type ColumnId = 'inProgress' | 'review' | 'done'

interface Task {
  id: string
  code: string
  title: string
  priority: 'low' | 'medium' | 'high'
  description?: string
  assignee?: string
  assigneeAvatar?: string
  dueDate?: string
  estimate?: string
  labels?: string[]
}

const COLUMN_META: Record<ColumnId, { title: string; eyebrow: string; accent: string; dot: string }> = {
  inProgress: {
    title: 'Building',
    eyebrow: 'In flight',
    accent: 'from-amber-600/20 via-amber-600/5 dark:from-amber-400/20 dark:via-amber-400/5 to-transparent',
    dot: 'bg-amber-500'
  },
  review: {
    title: 'QA Review',
    eyebrow: 'Validate',
    accent: 'from-violet-500/20 via-violet-500/5 to-transparent',
    dot: 'bg-violet-500'
  },
  done: {
    title: 'Shipped',
    eyebrow: 'Released',
    accent: 'from-green-600/20 via-green-600/5 dark:from-green-400/20 dark:via-green-400/5 to-transparent',
    dot: 'bg-green-600 dark:bg-green-400'
  }
}

const PRIORITY_STYLES: Record<Task['priority'], string> = {
  low: 'border-slate-200 bg-slate-50 text-slate-600 dark:border-slate-800 dark:bg-slate-900/60 dark:text-slate-300',
  medium:
    'border-amber-200 bg-amber-50 text-amber-700 dark:border-amber-900/70 dark:bg-amber-950/40 dark:text-amber-300',
  high: 'border-rose-200 bg-rose-50 text-rose-700 dark:border-rose-900/70 dark:bg-rose-950/40 dark:text-rose-300'
}

const INITIAL_COLUMNS: Record<ColumnId, Task[]> = {
  inProgress: [
    {
      id: '4',
      code: 'DS-31',
      title: 'Refresh component tokens',
      priority: 'high',
      description: 'Reconcile radius, shadow, and neutral color tokens across the workspace.',
      assignee: 'Emma Wilson',
      assigneeAvatar: 'https://cdn.shadcnstudio.com/ss-assets/avatar/avatar-1.png',
      dueDate: 'Aug 25',
      estimate: '8 pts',
      labels: ['Design system']
    },
    {
      id: '5',
      code: 'UI-19',
      title: 'Implement dark mode polish',
      priority: 'medium',
      description: 'Audit contrast, chart colors, and empty states for dark theme parity.',
      assignee: 'David Kim',
      assigneeAvatar: 'https://cdn.shadcnstudio.com/ss-assets/avatar/avatar-2.png',
      dueDate: 'Aug 28',
      estimate: '5 pts',
      labels: ['Theme', 'A11y']
    }
  ],
  review: [
    {
      id: '6',
      code: 'QA-04',
      title: 'Run invite flow regression',
      priority: 'medium',
      description: 'Verify workspace invites, role changes, and expired token states.',
      assignee: 'Nina Patel',
      assigneeAvatar: 'https://cdn.shadcnstudio.com/ss-assets/avatar/avatar-3.png',
      dueDate: 'Sep 06',
      estimate: '3 pts',
      labels: ['QA']
    }
  ],
  done: [
    {
      id: '7',
      code: 'OPS-01',
      title: 'Set up preview pipeline',
      priority: 'high',
      description: 'Ship isolated preview builds for every registry component change.',
      assignee: 'Aron Thompson',
      assigneeAvatar: 'https://cdn.shadcnstudio.com/ss-assets/avatar/avatar-4.png',
      dueDate: 'Sep 25',
      estimate: '5 pts',
      labels: ['CI']
    },
    {
      id: '8',
      code: 'GIT-02',
      title: 'Initial registry import',
      priority: 'low',
      description: 'Create the first grouped component entries with preview metadata.',
      assignee: 'James Brown',
      assigneeAvatar: 'https://cdn.shadcnstudio.com/ss-assets/avatar/avatar-5.png',
      dueDate: 'Sep 20',
      estimate: '1 pt',
      labels: ['Registry']
    }
  ]
}

interface TaskCardProps extends Omit<ComponentProps<typeof KanbanItem>, 'value' | 'children'> {
  task: Task
  isOverlay?: boolean
}

function TaskCard({ task, isOverlay, ...props }: TaskCardProps) {
  const initials = task.assignee
    ?.split(' ')
    .map(part => part[0])
    .join('')

  const cardContent = (
    <div
      className={cn(
        'bg-card text-card-foreground relative overflow-hidden rounded-lg border p-3 shadow-xs transition-shadow',
        !isOverlay && 'hover:shadow-sm'
      )}
    >
      <div className='space-y-3'>
        <div className='flex items-start justify-between gap-3'>
          <div className='min-w-0 space-y-1'>
            <div className='text-muted-foreground flex items-center gap-1.5 text-xs font-medium tracking-wide uppercase'>
              <span>{task.code}</span>
              {task.estimate && (
                <>
                  <span className='size-1 rounded-full bg-current opacity-40' />
                  <span>{task.estimate}</span>
                </>
              )}
            </div>
            <h3 className='line-clamp-2 text-sm leading-snug font-medium'>{task.title}</h3>
          </div>
          <span
            className={cn(
              'rounded-full border px-2 py-0.5 text-xs leading-4 font-medium capitalize',
              PRIORITY_STYLES[task.priority]
            )}
          >
            {task.priority}
          </span>
        </div>

        {task.description && (
          <p className='text-muted-foreground line-clamp-2 text-xs leading-relaxed'>{task.description}</p>
        )}

        {!!task.labels?.length && (
          <div className='flex flex-wrap gap-1.5'>
            {task.labels.map(label => (
              <span key={label} className='bg-muted text-muted-foreground rounded px-1.5 py-0.5 text-xs font-medium'>
                {label}
              </span>
            ))}
          </div>
        )}

        <div className='flex items-center justify-between gap-3 border-t pt-3'>
          {task.assignee && (
            <div className='flex min-w-0 items-center gap-2'>
              <Avatar className='size-6 border'>
                <AvatarImage src={task.assigneeAvatar} />
                <AvatarFallback className='text-xs'>{initials}</AvatarFallback>
              </Avatar>
              <span className='text-muted-foreground line-clamp-1 text-xs'>{task.assignee}</span>
            </div>
          )}
          {task.dueDate && (
            <time className='text-muted-foreground flex shrink-0 items-center gap-1 text-xs whitespace-nowrap tabular-nums'>
              <CalendarClockIcon className='size-3' />
              {task.dueDate}
            </time>
          )}
        </div>
      </div>
    </div>
  )

  return (
    <KanbanItem value={task.id} {...props}>
      {isOverlay ? cardContent : <KanbanItemHandle>{cardContent}</KanbanItemHandle>}
    </KanbanItem>
  )
}

interface TaskColumnProps extends Omit<ComponentProps<typeof KanbanColumn>, 'children' | 'value'> {
  value: ColumnId
  tasks: Task[]
  isOverlay?: boolean
}

function TaskColumn({ value, tasks, isOverlay, ...props }: TaskColumnProps) {
  const meta = COLUMN_META[value]

  return (
    <KanbanColumn value={value} {...props}>
      <div className='bg-muted/50 flex flex-col rounded-xl border p-2 shadow-xs'>
        <div className={cn('mb-2 rounded-lg bg-linear-to-r p-3', meta.accent)}>
          <div className='flex items-start justify-between gap-3'>
            <div className='space-y-1'>
              <div className='text-muted-foreground flex items-center gap-2 text-xs font-medium tracking-wide uppercase'>
                <span className={cn('size-2 rounded-full', meta.dot)} />
                {meta.eyebrow}
              </div>
              <div className='flex items-center gap-2'>
                <h2 className='text-sm font-semibold'>{meta.title}</h2>
                <Badge variant='outline'>{tasks.length}</Badge>
              </div>
            </div>
            <KanbanColumnHandle
              render={handleProps => (
                <Button {...handleProps} size='icon-xs' variant='ghost' aria-label={`Move ${meta.title} column`}>
                  <GripVerticalIcon
                  />
                </Button>
              )}
            />
          </div>
        </div>
        <KanbanColumnContent value={value} className='min-h-105 gap-2.5'>
          {tasks.map(task => (
            <TaskCard key={task.id} task={task} isOverlay={isOverlay} />
          ))}
        </KanbanColumnContent>
      </div>
    </KanbanColumn>
  )
}

const KanbanDemoModern = () => {
  const [columns, setColumns] = useState<Record<string, Task[]>>(INITIAL_COLUMNS)

  return (
    <div className='space-y-4 overflow-x-auto'>
      <Kanban
        value={columns}
        onValueChange={setColumns}
        getItemValue={item => item.id}
        className='mx-auto w-full max-w-4xl'
      >
        <KanbanBoard className='grid auto-rows-fr grid-cols-[repeat(3,minmax(16rem,1fr))] gap-3'>
          {Object.entries(columns).map(([columnId, tasks]) => (
            <TaskColumn key={columnId} value={columnId as ColumnId} tasks={tasks} />
          ))}
        </KanbanBoard>
        <KanbanOverlay>
          {({ value, variant }) => {
            const activeValue = String(value)

            if (variant === 'column') {
              return <TaskColumn value={activeValue as ColumnId} tasks={columns[activeValue] ?? []} isOverlay />
            }

            const task = Object.values(columns)
              .flat()
              .find(t => t.id === activeValue)

            return task ? <TaskCard task={task} isOverlay /> : null
          }}
        </KanbanOverlay>
      </Kanban>
    </div>
  )
}

export default KanbanDemoModern

import * as React from 'react'

import type { CSSProperties, ReactNode } from 'react'
import { createContext, useCallback, useContext, useLayoutEffect, useMemo, useRef, useState } from 'react'

import { mergeProps } from '@base-ui/react/merge-props'
import { useRender } from '@base-ui/react/use-render'

import type {
  DragEndEvent,
  DragOverEvent,
  DragStartEvent,
  DropAnimation,
  Modifiers,
  UniqueIdentifier,
  DraggableAttributes,
  DraggableSyntheticListeners
} from '@dnd-kit/core'

import {
  DndContext,
  DragOverlay,
  KeyboardSensor,
  MeasuringStrategy,
  PointerSensor,
  useSensor,
  useSensors,
  defaultDropAnimationSideEffects
} from '@dnd-kit/core'

import {
  arrayMove,
  defaultAnimateLayoutChanges,
  rectSortingStrategy,
  SortableContext,
  sortableKeyboardCoordinates,
  useSortable,
  verticalListSortingStrategy,
  type AnimateLayoutChanges
} from '@dnd-kit/sortable'
import { CSS } from '@dnd-kit/utilities'
import { createPortal } from 'react-dom'

import { cn } from '@astrale-os/ui/class-name'

// Stable module-level constants — never recreated, won't trigger dnd-kit effects
const measuringConfig = {
  droppable: { strategy: MeasuringStrategy.Always }
}

const pointerActivationConstraint = { distance: 10 }

interface KanbanContextProps<T> {
  columns: Record<string, T[]>
  setColumns: (columns: Record<string, T[]>) => void
  getItemId: (item: T) => string
  columnIds: string[]
  activeId: UniqueIdentifier | null
  setActiveId: (id: UniqueIdentifier | null) => void
  findContainer: (id: UniqueIdentifier) => string | undefined
  isColumn: (id: UniqueIdentifier) => boolean
  modifiers?: Modifiers
}

const KanbanContext = createContext<KanbanContextProps<any>>({
  columns: {},
  setColumns: () => {},
  getItemId: () => '',
  columnIds: [],
  activeId: null,
  setActiveId: () => {},
  findContainer: () => undefined,
  isColumn: () => false,
  modifiers: undefined
})

const ColumnContext = createContext<{
  attributes: DraggableAttributes
  listeners: DraggableSyntheticListeners | undefined
  isDragging?: boolean
  disabled?: boolean
}>({
  attributes: {} as DraggableAttributes,
  listeners: undefined,
  isDragging: false,
  disabled: false
})

const ItemContext = createContext<{
  listeners: DraggableSyntheticListeners | undefined
  isDragging?: boolean
  disabled?: boolean
}>({
  listeners: undefined,
  isDragging: false,
  disabled: false
})

const IsOverlayContext = createContext(false)

const animateLayoutChanges: AnimateLayoutChanges = args => defaultAnimateLayoutChanges({ ...args, wasDragging: true })

const dropAnimationConfig: DropAnimation = {
  sideEffects: defaultDropAnimationSideEffects({
    styles: { active: { opacity: '0.4' } }
  })
}

export interface KanbanMoveEvent {
  event: DragEndEvent
  activeContainer: string
  activeIndex: number
  overContainer: string
  overIndex: number
}

export interface KanbanRootProps<T> extends Omit<useRender.ComponentProps<'div'>, 'children'> {
  value: Record<string, T[]>
  onValueChange: (value: Record<string, T[]>) => void
  getItemValue: (item: T) => string
  children: ReactNode
  onMove?: (event: KanbanMoveEvent) => void
  modifiers?: Modifiers
}

function Kanban<T>({
  value,
  onValueChange,
  getItemValue,
  children,
  className,
  render,
  onMove,
  modifiers,
  ...props
}: KanbanRootProps<T>) {
  const columns = value
  const setColumns = onValueChange
  const [activeId, setActiveId] = useState<UniqueIdentifier | null>(null)

  // Refs so all callbacks read the latest values without being recreated on every render.
  // This breaks the cascade: columns change → callbacks recreate → DndContext re-registers → loop.
  const columnsRef = useRef(columns)

  columnsRef.current = columns

  const getItemValueRef = useRef(getItemValue)

  getItemValueRef.current = getItemValue

  const onMoveRef = useRef(onMove)

  onMoveRef.current = onMove

  // Sensor config objects are stable module-level constants, so useSensors result is stable.
  const sensors = useSensors(
    useSensor(PointerSensor, { activationConstraint: pointerActivationConstraint }),
    useSensor(KeyboardSensor, { coordinateGetter: sortableKeyboardCoordinates })
  )

  const columnIds = useMemo(() => Object.keys(columns), [columns])

  // isColumn only depends on columnIds (the keys, not the item arrays). Column keys don't
  // change when items are moved, so columnIds array values are stable during drags.
  const isColumn = useCallback((id: UniqueIdentifier) => columnIds.includes(id as string), [columnIds])

  // findContainer reads columnsRef so it doesn't need columns or getItemValue in its deps.
  const findContainer = useCallback(
    (id: UniqueIdentifier) => {
      if (isColumn(id)) return id as string
      const cols = columnsRef.current
      const getId = getItemValueRef.current

      return Object.keys(cols).find(key => cols[key].some(item => getId(item) === id))
    },
    [isColumn]
  )

  const handleDragStart = useCallback((event: DragStartEvent) => {
    setActiveId(event.active.id)
  }, [])

  // RAF refs throttle onDragOver: we only process the latest event per animation frame.
  // This prevents React from receiving dozens of setState calls per frame during rapid drags,
  // which is what causes "Maximum update depth exceeded".
  const dragOverRafRef = useRef<number | null>(null)
  const pendingDragOverRef = useRef<DragOverEvent | null>(null)

  const handleDragOver = useCallback(
    (event: DragOverEvent) => {
      if (onMoveRef.current) return

      // Always capture the latest event; only one RAF runs at a time.
      pendingDragOverRef.current = event
      if (dragOverRafRef.current !== null) return

      dragOverRafRef.current = requestAnimationFrame(() => {
        dragOverRafRef.current = null
        const latestEvent = pendingDragOverRef.current

        pendingDragOverRef.current = null
        if (!latestEvent) return

        const { active, over } = latestEvent

        if (!over) return
        if (isColumn(active.id)) return

        const activeContainer = findContainer(active.id)
        const overContainer = findContainer(over.id)

        // Only reorder within the same column during drag. Cross-column moves are
        // committed in onDragEnd instead — moving an item to another column unmounts
        // its DOM node and remounts it, which releases pointer capture and causes the
        // drag to end prematurely when the kanban is rendered inside an iframe.
        if (!activeContainer || !overContainer || activeContainer !== overContainer) return

        const cols = columnsRef.current
        const getId = getItemValueRef.current
        const activeIndex = cols[activeContainer].findIndex((item: T) => getId(item) === active.id)
        const overIndex = cols[activeContainer].findIndex((item: T) => getId(item) === over.id)

        if (activeIndex === overIndex) return

        setColumns({
          ...cols,
          [activeContainer]: arrayMove(cols[activeContainer], activeIndex, overIndex)
        })
      })
    },
    [findContainer, isColumn, setColumns]
  )

  const flushPendingDragOver = useCallback(() => {
    if (dragOverRafRef.current !== null) {
      cancelAnimationFrame(dragOverRafRef.current)
      dragOverRafRef.current = null
    }

    pendingDragOverRef.current = null
  }, [])

  const handleDragCancel = useCallback(() => {
    flushPendingDragOver()
    setActiveId(null)
  }, [flushPendingDragOver])

  const handleDragEnd = useCallback(
    (event: DragEndEvent) => {
      flushPendingDragOver()

      const { active, over } = event

      setActiveId(null)

      if (!over) return

      if (onMoveRef.current && !isColumn(active.id)) {
        const cols = columnsRef.current
        const getId = getItemValueRef.current
        const activeContainer = findContainer(active.id)
        const overContainer = findContainer(over.id)

        if (activeContainer && overContainer) {
          const activeIndex = cols[activeContainer].findIndex((item: T) => getId(item) === active.id)

          const overIndex = isColumn(over.id)
            ? cols[overContainer].length
            : cols[overContainer].findIndex((item: T) => getId(item) === over.id)

          onMoveRef.current({ event, activeContainer, activeIndex, overContainer, overIndex })
        }

        return
      }

      if (isColumn(active.id) && isColumn(over.id)) {
        const cols = columnsRef.current
        const keys = Object.keys(cols)
        const activeIndex = keys.indexOf(active.id as string)
        const overIndex = keys.indexOf(over.id as string)

        if (activeIndex !== overIndex) {
          const newOrder = arrayMove(keys, activeIndex, overIndex)
          const newColumns: Record<string, T[]> = {}

          newOrder.forEach(key => {
            newColumns[key] = cols[key]
          })

          setColumns(newColumns)
        }

        return
      }

      const activeContainer = findContainer(active.id)
      const overContainer = findContainer(over.id)

      if (!activeContainer || !overContainer) return

      const cols = columnsRef.current
      const getId = getItemValueRef.current
      const activeIndex = cols[activeContainer].findIndex((item: T) => getId(item) === active.id)

      if (activeContainer === overContainer) {
        const overIndex = cols[overContainer].findIndex((item: T) => getId(item) === over.id)

        if (activeIndex !== overIndex) {
          setColumns({
            ...cols,
            [activeContainer]: arrayMove(cols[activeContainer], activeIndex, overIndex)
          })
        }

        return
      }

      const overItems = cols[overContainer]

      const overIndex = isColumn(over.id) ? overItems.length : overItems.findIndex((item: T) => getId(item) === over.id)

      const newActiveItems = [...cols[activeContainer]]
      const newOverItems = [...overItems]
      const [movedItem] = newActiveItems.splice(activeIndex, 1)

      newOverItems.splice(overIndex, 0, movedItem)

      setColumns({ ...cols, [activeContainer]: newActiveItems, [overContainer]: newOverItems })
    },
    [findContainer, isColumn, setColumns, flushPendingDragOver]
  )

  // Stable getItemId wrapper so context consumers don't re-render when the parent
  // passes a new inline arrow function reference.
  const stableGetItemId = useCallback((item: T) => getItemValueRef.current(item), [])

  const contextValue = useMemo(
    () => ({
      columns,
      setColumns,
      getItemId: stableGetItemId,
      columnIds,
      activeId,
      setActiveId,
      findContainer,
      isColumn,
      modifiers
    }),
    [columns, setColumns, stableGetItemId, columnIds, activeId, findContainer, isColumn, modifiers]
  )

  const defaultProps = {
    'data-slot': 'kanban',
    'data-dragging': activeId !== null,
    className: cn(activeId !== null && 'cursor-grabbing!', className),
    children
  }

  return (
    <KanbanContext.Provider value={contextValue}>
      <DndContext
        sensors={sensors}
        modifiers={modifiers}
        measuring={measuringConfig}
        onDragStart={handleDragStart}
        onDragOver={handleDragOver}
        onDragEnd={handleDragEnd}
        onDragCancel={handleDragCancel}
      >
        {useRender({
          defaultTagName: 'div',
          render,
          props: mergeProps<'div'>(defaultProps, props)
        })}
      </DndContext>
    </KanbanContext.Provider>
  )
}

export type KanbanBoardProps = useRender.ComponentProps<'div'>

function KanbanBoard({ className, render, ...props }: KanbanBoardProps) {
  const { columnIds } = useContext(KanbanContext)

  const defaultProps = {
    'data-slot': 'kanban-board',
    className: cn('grid auto-rows-fr gap-4 sm:grid-cols-3', className),
    children: props.children
  }

  return (
    <SortableContext items={columnIds} strategy={rectSortingStrategy}>
      {useRender({
        defaultTagName: 'div',
        render,
        props: mergeProps<'div'>(defaultProps, props)
      })}
    </SortableContext>
  )
}

export interface KanbanColumnProps extends useRender.ComponentProps<'div'> {
  value: string
  disabled?: boolean
}

function KanbanColumn({ value, className, render, disabled, ...props }: KanbanColumnProps) {
  const isOverlay = useContext(IsOverlayContext)

  const {
    setNodeRef,
    transform,
    transition,
    attributes,
    listeners,
    isDragging: isSortableDragging
  } = useSortable({
    id: value,
    disabled: disabled || isOverlay,
    animateLayoutChanges
  })

  if (isOverlay) {
    const defaultProps = {
      'data-slot': 'kanban-column',
      'data-value': value,
      'data-dragging': true,
      className: cn('group/kanban-column flex flex-col', className),
      children: props.children
    }

    return (
      <ColumnContext.Provider
        value={{
          attributes: {} as DraggableAttributes,
          listeners: undefined,
          isDragging: true,
          disabled: false
        }}
      >
        {useRender({
          defaultTagName: 'div',
          render,
          props: mergeProps<'div'>(defaultProps, props)
        })}
      </ColumnContext.Provider>
    )
  }

  const { activeId, isColumn } = useContext(KanbanContext)
  const isColumnDragging = activeId ? isColumn(activeId) : false

  const style = {
    transition,
    transform: CSS.Transform.toString(transform)
  } as CSSProperties

  const defaultProps = {
    'data-slot': 'kanban-column',
    'data-value': value,
    'data-dragging': isSortableDragging,
    'data-disabled': disabled,
    ref: setNodeRef,
    style,
    className: cn(
      'group/kanban-column flex flex-col',
      isSortableDragging && 'opacity-50 z-50',
      disabled && 'opacity-50',
      className
    ),
    children: props.children
  }

  return (
    <ColumnContext.Provider value={{ attributes, listeners, isDragging: isColumnDragging, disabled }}>
      {useRender({
        defaultTagName: 'div',
        render,
        props: mergeProps<'div'>(defaultProps, props)
      })}
    </ColumnContext.Provider>
  )
}

export interface KanbanColumnHandleProps extends useRender.ComponentProps<'div'> {
  cursor?: boolean
}

function KanbanColumnHandle({ className, render, cursor = true, ...props }: KanbanColumnHandleProps) {
  const { attributes, listeners, isDragging, disabled } = useContext(ColumnContext)

  const defaultProps = {
    'data-slot': 'kanban-column-handle',
    'data-dragging': isDragging,
    'data-disabled': disabled,
    suppressHydrationWarning: true,
    ...attributes,
    ...listeners,
    className: cn(
      'opacity-0 transition-opacity group-hover/kanban-column:opacity-100',
      cursor && (isDragging ? 'cursor-grabbing!' : 'cursor-grab!'),
      className
    ),
    children: props.children
  }

  return useRender({
    defaultTagName: 'div',
    render,
    props: mergeProps<'div'>(defaultProps, props)
  })
}

export interface KanbanItemProps extends useRender.ComponentProps<'div'> {
  value: string
  disabled?: boolean
}

function KanbanItem({ value, className, render, disabled, ...props }: KanbanItemProps) {
  const isOverlay = useContext(IsOverlayContext)

  const {
    setNodeRef,
    transform,
    transition,
    attributes,
    listeners,
    isDragging: isSortableDragging
  } = useSortable({
    id: value,
    disabled: disabled || isOverlay,
    animateLayoutChanges
  })

  if (isOverlay) {
    const defaultProps = {
      'data-slot': 'kanban-item',
      'data-value': value,
      'data-dragging': true,
      className: cn(className),
      children: props.children
    }

    return (
      <ItemContext.Provider value={{ listeners: undefined, isDragging: true, disabled: false }}>
        {useRender({
          defaultTagName: 'div',
          render,
          props: mergeProps<'div'>(defaultProps, props)
        })}
      </ItemContext.Provider>
    )
  }

  const { activeId, isColumn } = useContext(KanbanContext)
  const isItemDragging = activeId ? !isColumn(activeId) : false

  const style = {
    transition,
    transform: CSS.Transform.toString(transform)
  } as CSSProperties

  const defaultProps = {
    'data-slot': 'kanban-item',
    'data-value': value,
    'data-dragging': isSortableDragging,
    'data-disabled': disabled,
    suppressHydrationWarning: true,
    ref: setNodeRef,
    style,
    ...attributes,
    className: cn(isSortableDragging && 'opacity-50 z-50', disabled && 'opacity-50', className),
    children: props.children
  }

  return (
    <ItemContext.Provider value={{ listeners, isDragging: isItemDragging, disabled }}>
      {useRender({
        defaultTagName: 'div',
        render,
        props: mergeProps<'div'>(defaultProps, props)
      })}
    </ItemContext.Provider>
  )
}

export interface KanbanItemHandleProps extends useRender.ComponentProps<'div'> {
  cursor?: boolean
}

function KanbanItemHandle({ className, render, cursor = true, ...props }: KanbanItemHandleProps) {
  const { listeners, isDragging, disabled } = useContext(ItemContext)

  const defaultProps = {
    'data-slot': 'kanban-item-handle',
    'data-dragging': isDragging,
    'data-disabled': disabled,
    ...listeners,
    className: cn(cursor && (isDragging ? 'cursor-grabbing!' : 'cursor-grab!'), className),
    children: props.children
  }

  return useRender({
    defaultTagName: 'div',
    render,
    props: mergeProps<'div'>(defaultProps, props)
  })
}

export interface KanbanColumnContentProps extends useRender.ComponentProps<'div'> {
  value: string
}

function KanbanColumnContent({ value, className, render, ...props }: KanbanColumnContentProps) {
  const { columns, getItemId } = useContext(KanbanContext)

  const itemIds = useMemo(() => columns[value].map(getItemId), [columns, getItemId, value])

  const defaultProps = {
    'data-slot': 'kanban-column-content',
    className: cn('flex flex-col gap-2', className),
    children: props.children
  }

  return (
    <SortableContext items={itemIds} strategy={verticalListSortingStrategy}>
      {useRender({
        defaultTagName: 'div',
        render,
        props: mergeProps<'div'>(defaultProps, props)
      })}
    </SortableContext>
  )
}

export interface KanbanOverlayProps extends Omit<React.ComponentProps<typeof DragOverlay>, 'children'> {
  children?: ReactNode | ((params: { value: UniqueIdentifier; variant: 'column' | 'item' }) => ReactNode)
}

function KanbanOverlay({ children, className, ...props }: KanbanOverlayProps) {
  const { activeId, isColumn, modifiers } = useContext(KanbanContext)
  const [mounted, setMounted] = useState(false)

  useLayoutEffect(() => setMounted(true), [])

  const variant = activeId ? (isColumn(activeId) ? 'column' : 'item') : 'item'

  const content =
    activeId && children ? (typeof children === 'function' ? children({ value: activeId, variant }) : children) : null

  if (!mounted) return null

  return createPortal(
    <DragOverlay
      dropAnimation={dropAnimationConfig}
      modifiers={modifiers}
      className={cn('z-50', activeId && 'cursor-grabbing', className)}
      {...props}
    >
      <IsOverlayContext.Provider value={true}>{content}</IsOverlayContext.Provider>
    </DragOverlay>,
    document.body
  )
}

